/// `ModalBottomSheet`'s default `drag_handle`: `BottomSheetDefaults::drag_handle`, one callback
/// per thread (the same every pass, so the sheet can skip).
#[doc(hidden)]
pub fn default_drag_handle() -> Option<compose_runtime::Callback> {
    thread_local! {
        static HANDLE: compose_runtime::Callback =
            compose_runtime::callback(BottomSheetDefaults::drag_handle);
    }
    Some(HANDLE.with(Clone::clone))
}
